import{_ as i,o as a,c as e,a2 as r}from"./chunks/framework.BXzK3EA4.js";const b=JSON.parse('{"title":"국가 07 용산철도후국","description":"","frontmatter":{},"headers":[],"relativePath":"world/Cast-State-07.md","filePath":"world/Cast-State-07.md"}'),t={name:"world/Cast-State-07.md"};function h(o,l,u,n,d,s){return a(),e("div",null,[...l[0]||(l[0]=[r('<h1 id="국가-07-용산철도후국" tabindex="-1">국가 07 용산철도후국 <a class="header-anchor" href="#국가-07-용산철도후국" aria-label="Permalink to &quot;국가 07 용산철도후국&quot;">​</a></h1><p>철도조정관 박태겸을 둘러싼 선로 가문 원로와 배차원·도제다.</p><h3 id="인물-신가온" tabindex="-1">인물 신가온 <a class="header-anchor" href="#인물-신가온" aria-label="Permalink to &quot;인물 신가온&quot;">​</a></h3><ul><li>소속: 용산철도후국</li><li>직위: 선로 가문 원로</li><li>성격: 가문의 궤도를 혈통으로 보고 양자를 손님으로 대한다. 겉으로는 예의를 지키지만 배차 거부권만은 절대 놓지 않는다.</li><li>개인 야망: 박태겸의 도제 승계를 무효로 돌리고 선로 가문이 후국회의의 최종 거부권을 세습하게 한다.</li><li>공포: 사방 강국이 용산을 전쟁터로 쓰면서 가문 창고의 환적 독점까지 빼앗기는 것.</li><li>통치 방식: 가문 회의에서만 선로 봉쇄를 승인하고, 도제 숙소의 배급을 끊는 방식으로 조정관을 압박한다.</li><li>핵심 관계: 박태겸과 후계를 놓고 경쟁하며 임초원의 귀환 열차를 억류했다. 강다은을 가문 측 배차로 부리고, 황노을에게는 창동 차륜 공급을 조건으로 건다.</li><li>촉발 사건: 임초원을 태운 열차가 용산 창에 들어오자 선로 전환기를 잠그고 후국회의를 소집했다.</li><li>플레이어 개입: 전환기 열쇠를 훔치거나, 가문회의에서 양자 승계를 공개 지지할 수 있다.</li></ul><h3 id="인물-권시온" tabindex="-1">인물 권시온 <a class="header-anchor" href="#인물-권시온" aria-label="Permalink to &quot;인물 권시온&quot;">​</a></h3><ul><li>소속: 용산철도후국</li><li>직위: 열차 배차원</li><li>성격: 실리적이나 시각표를 어기는 사람을 가혹하게 다룬다. 어느 진영 열차든 시간을 지키면 얼굴을 가리지 않는다.</li><li>개인 야망: 서부 급수열차와 동부 군수열차를 같은 배차표에 묶어 용산을 수문헌장 밖의 필수 중계로 남긴다.</li><li>공포: 한재목의 철도계약이 독점 조항으로 바뀌어 배차권이 수문 아래로 빨려 들어가는 것.</li><li>통치 방식: 상호 인질 대신 도제 탑승을 증명으로 받고, 편도만 온 열차는 창에서 하루를 묶는다.</li><li>핵심 관계: 박태겸의 지휘로 한재목의 서부 철도계약을 운용한다. 오서율에게 계약 공증을 맡기고, 송이든과 창고 환적 순서를 나눈다.</li><li>촉발 사건: 뚝도 급수계약 만료 소식이 용산 배차판에 붙자 서부 급수열차가 창 점유를 하루 더 요구했다.</li><li>플레이어 개입: 급수열차의 창 점유를 중재하거나, 독점 배차 밀약을 기록청에 넘길 수 있다.</li></ul><h3 id="인물-황지호" tabindex="-1">인물 황지호 <a class="header-anchor" href="#인물-황지호" aria-label="Permalink to &quot;인물 황지호&quot;">​</a></h3><ul><li>소속: 용산철도후국</li><li>직위: 선로 도제</li><li>성격: 침착하고 손끝이 정확하지만 가문 앞에서 목소리가 작아진다. 숙련으로 자리를 증명해야 한다는 강박이 있다.</li><li>개인 야망: 박태겸의 양자 기술자 경로로 후계가 되어 혈연 선로가문의 거부권을 배차표에서 지운다.</li><li>공포: 자신이 임초원을 끌어들이기 위한 미끼 도제로 소비되는 것.</li><li>통치 방식: 정비 일지를 공개하고 가문 원로의 구두 지시를 문장으로 다시 받아 적는다.</li><li>핵심 관계: 박태겸의 도제이며 김도윤과 교환된 창동 수련을 거쳤다. 송하율과 제동 부품을 나누고, 신가온의 배급 압박을 받는다.</li><li>촉발 사건: 임초원 억류 열차의 제동 점검을 도제에게 맡기라는 명령과 손대지 말라는 가문 명령이 동시에 떨어졌다.</li><li>플레이어 개입: 도제의 정비 권한을 증언하거나, 그를 창동으로 빼내 가문 회의를 흔들 수 있다.</li></ul><h3 id="인물-송이든" tabindex="-1">인물 송이든 <a class="header-anchor" href="#인물-송이든" aria-label="Permalink to &quot;인물 송이든&quot;">​</a></h3><ul><li>소속: 용산철도후국</li><li>직위: 환적 배차원</li><li>성격: 사교적이지만 창고 열쇠는 몸에서 떼지 않는다. 빈 상자를 가득 찬 것처럼 적는 사람을 원수로 본다.</li><li>개인 야망: 냉동 화물과 폐전자 회수를 용산 창고 신용으로 묶어 오해린의 결제권과 별개인 환적 원장을 만든다.</li><li>공포: 전력 없는 밤에 냉동 화물이 녹아 후국의 중계 신용이 하루 만에 무너지는 것.</li><li>통치 방식: 창고 온도를 두 시간에 한 번 소리 내어 읽고, 허위 재고가 나오면 해당 가문 칸을 봉쇄한다.</li><li>핵심 관계: 박태겸에게 창고 임대 장부를 보고하고 서나연의 얼음 벽돌을 환적한다. 신태산과는 호송 도착 시각을 맞춘다.</li><li>촉발 사건: 노량진 정전 소문이 용산에 닿자 냉동 칸 임차인들이 화물을 밤사이에 빼내기 시작했다.</li><li>플레이어 개입: 얼음과 축전지를 보급하거나, 녹은 재고를 숨긴 칸을 봉인해 공개할 수 있다.</li></ul><h3 id="인물-강다은" tabindex="-1">인물 강다은 <a class="header-anchor" href="#인물-강다은" aria-label="Permalink to &quot;인물 강다은&quot;">​</a></h3><ul><li>소속: 용산철도후국</li><li>직위: 선로 가문 배차원</li><li>성격: 대담하고 기회에 빠르다. 가문의 이름을 방패로 쓰면서도 조정관의 배차표를 빈칸처럼 다룬다.</li><li>개인 야망: 가문 거부권과 박태겸의 도제 승계를 동시에 거래해 자신이 후국회의의 실제 배차 키를 쥔다.</li><li>공포: 양편을 걸다 들켜 선로 봉쇄대의 인질로 남는 것.</li><li>통치 방식: 가문 칸과 공공 칸의 배차를 섞어 놓고, 막판에 전환기로 이익이 큰 쪽을 연다.</li><li>핵심 관계: 신가온의 지휘를 받지만 박태겸에게 가문 동향을 팔아 빚을 졌다. 조우찬에게 창동 시험 차륜을 빼돌린 의혹이 있다.</li><li>촉발 사건: 억류 열차의 전환기 키가 가문 금고와 조정관실에 하나씩 있다는 소문이 배차판에 붙었다.</li><li>플레이어 개입: 어느 쪽 키를 살릴지 고르거나, 양다리 배차 장부를 후국회의에 펼칠 수 있다.</li></ul><h3 id="인물-양건우" tabindex="-1">인물 양건우 <a class="header-anchor" href="#인물-양건우" aria-label="Permalink to &quot;인물 양건우&quot;">​</a></h3><ul><li>소속: 용산철도후국</li><li>직위: 용산창 제동 정비사</li><li>성격: 제동 마모로 야간 운행 거리를 읽고, 공구함 뚜껑을 열어 두는 도제를 교대에서 뺀다. 말수는 적고 시운전 소음으로 대답한다.</li><li>개인 야망: 용산 창의 제동 주기를 공개 정비표로 묶어 혈연 가문의 구두 지시가 출고를 막지 못하게 한다.</li><li>공포: 가문 창고의 환적 독점이 제동 부품까지 잠가 억류 열차가 창에 박히는 것.</li><li>통치 방식: 출고 전 제동 두께를 칠판에 쓰고, 창동 시험 도장 없는 부품은 달지 않는다.</li><li>핵심 관계: 황지호의 정비 일지를 현장에서 집행하는 사제이고, 박태겸의 도제 경로를 창에서 받치며, 김도윤의 교환 수련 규격을 검수한다.</li><li>촉발 사건: 억류 열차의 제동 점검 명령과 손대지 말라는 가문 명령이 동시에 떨어지자 양건우는 일지만 공개하고 분해는 보류한다.</li><li>플레이어 개입: 도제의 정비 권한을 증언하거나, 도장 없는 부품의 발주자를 밝혀 정비사를 흔들 수 있다.</li></ul><h3 id="인물-주서람" tabindex="-1">인물 주서람 <a class="header-anchor" href="#인물-주서람" aria-label="Permalink to &quot;인물 주서람&quot;">​</a></h3><ul><li>소속: 용산철도후국</li><li>직위: 환적창고 물류상</li><li>성격: 빈 상자를 가득 찬 것처럼 적는 사람을 원수로 보고, 온도가 흔들리면 표정이 굳는다. 창고 열쇠는 몸에서 떼지 않는다.</li><li>개인 야망: 냉동 화물과 폐전자 회수를 용산 창고 신용으로 묶어 오해린의 결제권과 별개인 환적 원장을 현장화한다.</li><li>공포: 전력 없는 밤에 냉동 화물이 녹아 중계 신용이 하루 만에 무너지는 것.</li><li>통치 방식: 창고 온도를 두 시간에 한 번 소리 내어 읽고, 허위 재고가 나오면 해당 가문 칸을 봉쇄한다.</li><li>핵심 관계: 송이든의 환적 순서를 현장에서 집행하는 계약이고, 서나연의 얼음 벽돌을 인계하며, 신태산의 호송 도착 시각을 맞춘다.</li><li>촉발 사건: 노량진 정전 소문이 용산에 닿자 주서람은 밤사이 빼내기 시작한 화물을 칸 단위로 봉한다.</li><li>플레이어 개입: 얼음과 축전지를 보급하거나, 녹은 재고를 숨긴 칸을 봉인해 공개할 수 있다.</li></ul><h3 id="인물-차호민" tabindex="-1">인물 차호민 <a class="header-anchor" href="#인물-차호민" aria-label="Permalink to &quot;인물 차호민&quot;">​</a></h3><ul><li>소속: 용산철도후국</li><li>직위: 용산창 의무원</li><li>성격: 선로 화상보다 냉동 칸 동상을 먼저 맡고, 도제 숙소 배급을 치료 순서로 바꾸라는 쪽지를 찢는다. 온화하나 소독수가 비면 창 진료를 닫는다.</li><li>개인 야망: 선로 가문과 도제 노동자의 방역 주기를 후국회의 부칙으로 올려 배급 압박에도 의무 최저선을 남긴다.</li><li>공포: 억류 열차의 부상자가 인질 명부로만 남아 의무실이 가문 감옥이 되는 것.</li><li>통치 방식: 환자 명부와 시약 묶음을 동시에 게시하고, 가문 칸 환자는 공공 칸과 분리해 받는다.</li><li>핵심 관계: 황지호의 도제 숙소를 진료로 받치고, 류은비에게 창 약재를 빚지며, 임초원의 억류 열차 탑승자 진료를 우선한다.</li><li>촉발 사건: 임초원 억류 열차가 창에 들어오자 차호민은 가문 회송보다 탑승자 진료를 먼저 열고 배급 중단 압박을 거부한다.</li><li>플레이어 개입: 대체 시약을 호송해 진료를 유지하거나, 인질 명단을 가문에 넘겨 의무원을 위태롭게 할 수 있다.</li></ul><h3 id="인물-설민우" tabindex="-1">인물 설민우 <a class="header-anchor" href="#인물-설민우" aria-label="Permalink to &quot;인물 설민우&quot;">​</a></h3><ul><li>소속: 용산철도후국</li><li>직위: 선로 봉쇄 순찰대 조장</li><li>성격: 전환기 쇳소리로 무단 진입을 읽고, 편도만 온 열차를 사고보다 고의로 본다. 부하의 배급이 끊기면 자신이 선로를 먼저 걷는다.</li><li>개인 야망: 선로 봉쇄를 후국회의 공개 암호패로만 움직여 가문 금고의 키가 단독으로 전환기를 잠그지 못하게 한다.</li><li>공포: 사방 강국이 용산을 전쟁터로 쓰며 봉쇄대가 어느 편 사병이 되는 것.</li><li>통치 방식: 순찰 시각을 배차판에 쓰되, 전환기는 박태겸과 신가온의 키가 동시에 있어야 연다.</li><li>핵심 관계: 신가온의 가문 봉쇄 지시를 현장에서 받되 박태겸의 공식 배차표를 우선하고, 나길호의 역 방송을 봉쇄 시각과 맞춘다.</li><li>촉발 사건: 임초원을 태운 열차가 창에 들어오자 설민우는 전환기를 잠그라는 가문 명령을 보류하고 후국회의 소집만 지킨다.</li><li>플레이어 개입: 전환기 열쇠를 어느 쪽에 넘길지 고르거나, 암호패 유출을 폭로해 조장을 교체하게 할 수 있다.</li></ul><h3 id="인물-지온유" tabindex="-1">인물 지온유 <a class="header-anchor" href="#인물-지온유" aria-label="Permalink to &quot;인물 지온유&quot;">​</a></h3><ul><li>소속: 용산철도후국</li><li>직위: 후국회의 전령</li><li>성격: 봉인 끈이 느슨하면 출발을 거부하고, 구두 배차 거부를 원장에 올리지 않는 원로를 위반자로 부른다. 숨이 차도 사본 두 장을 한 손에 쥔다.</li><li>개인 야망: 도제 승계와 선로 봉쇄 통지를 자신이 날인하는 전령 원장에만 유효하게 만든다.</li><li>공포: 위조 회의 전갈 한 장이 양자 승계를 무효로 돌려 전령망이 가문 나팔이 되는 것.</li><li>통치 방식: 전갈을 조정관실과 가문 회의에 동시에 보내고, 억류 통지는 권시온의 배차 날인과 박태겸의 연서가 둘 다 있어야 달린다.</li><li>핵심 관계: 박태겸의 후계 제안을 봉인 상태로만 나르는 지휘이고, 권시온의 배차 변경을 배달하는 계약이며, 양해온의 인준 전갈과 시점을 맞춘다.</li><li>촉발 사건: 억류 열차의 전환기 키가 둘이라는 소문이 배차판에 붙자 지온유는 승계 무효 전갈을 가방에 잠근다.</li><li>플레이어 개입: 위조 전갈을 찾아 봉인을 지키거나, 가방 속 보류 문서를 가문회의에 펼칠 수 있다.</li></ul><h3 id="인물-마하린" tabindex="-1">인물 마하린 <a class="header-anchor" href="#인물-마하린" aria-label="Permalink to &quot;인물 마하린&quot;">​</a></h3><ul><li>소속: 용산철도후국</li><li>직위: 한강 북안 폐선 탐사원</li><li>성격: 강변 폐선의 수온으로 시간을 읽고, 지도에 없는 측선을 자랑으로 여기지 않는다. 늦은 보고를 죄로 본다.</li><li>개인 야망: 용산 접속과 강변 우회 측선을 한 장의 공개 해도로 그려 중계국이 전쟁 없이 우회 배차하게 한다.</li><li>공포: 탐사 경로가 군사 비밀로 봉인되어 측선이 강국의 침투로로 팔리는 것.</li><li>통치 방식: 채수와 레일 상태를 같은 원장에 남기고, 붕괴 구간은 조정관과 가문 원로가 동시에 서명해야 표시한다.</li><li>핵심 관계: 박태겸에게 우회 좌표를 넘기는 동맹이고, 주리안의 북부 배관 점선과 강변을 맞추며, 설민우의 봉쇄 순찰과 맨홀 출입을 나눈다.</li><li>촉발 사건: 사방 강국이 창 점유를 늘리자 마하린은 단독 측선 측량으로 우회를 열고 가문의 독점 경로와 충돌한다.</li><li>플레이어 개입: 측선 호위를 맡아 우회 배차를 성사시키거나, 비밀 침투로 표시를 폭로할 수 있다.</li></ul><h3 id="인물-연시완" tabindex="-1">인물 연시완 <a class="header-anchor" href="#인물-연시완" aria-label="Permalink to &quot;인물 연시완&quot;">​</a></h3><ul><li>소속: 용산철도후국</li><li>직위: 열차 배차원장 기록관</li><li>성격: 시간표의 빈칸을 사람보다 먼저 메우고, 구두 감면을 원장에 올리지 않는 배차원을 위반자로 부른다. 숫자는 공개하되 해석은 난외에 남긴다.</li><li>개인 야망: 서부 급수열차와 동부 군수열차를 자신이 감수한 배차 원장에만 유효하게 해 용산이 수문헌장 밖의 필수 중계로 남게 한다.</li><li>공포: 위조 통행증 한 장이 창을 가득 채워 급수열차와 환적 화차가 동시에 갇히는 것.</li><li>통치 방식: 배차 사본을 배차판과 후국회에 동시에 붙이고, 비상 점유도 하루 안의 재계산 없이는 무효라고 못 박는다.</li><li>핵심 관계: 권시온의 배차 선언을 원장으로 옮기는 사제이고, 오서율의 철도계약 공증을 검증하며, 한재목의 서부 철도계약 요율을 난외에 적는다.</li><li>촉발 사건: 뚝도 급수계약 만료 소식이 배차판에 붙자 연시완은 서부 급수열차의 창 점유 연장을 원장에 올리고 사적 감면을 거부한다.</li><li>플레이어 개입: 우회 허가 증인을 호송하거나, 난외 착복 노트를 폭로해 기록관을 교체하게 할 수 있다.</li></ul><h3 id="인물-나길호" tabindex="-1">인물 나길호 <a class="header-anchor" href="#인물-나길호" aria-label="Permalink to &quot;인물 나길호&quot;">​</a></h3><ul><li>소속: 용산철도후국</li><li>직위: 용산역 대합실 역장</li><li>성격: 승강장 습기로 환적인파를 가늠하고, 도제 대기열을 가문 화차 뒤로 미루라는 명령을 모욕으로 듣는다. 온화하나 억류 예고가 뜨면 방송을 직접 잡는다.</li><li>개인 야망: 용산 대합실을 배차·환적·진료가 한 지붕에서 서명되는 중계 허브로 만들어 후국의 대면 창구가 된다.</li><li>공포: 전쟁 소문만으로 대합실이 봉쇄되고 중계 인파가 강변 밀선으로 흩어지는 것.</li><li>통치 방식: 대합실 환적 창구와 의무 대기표를 매일 공개하고, 장갑 화물차는 급수열차가 떠난 뒤에만 승강장에 붙인다.</li><li>핵심 관계: 차호민의 창 진료 봉쇄를 방송으로 알리는 동맹이고, 권시온의 배차 순서를 승강장에서 집행하며, 송이든의 창고 임대 순번을 칠판에 옮겨 적는다.</li><li>촉발 사건: 임초원 억류 소식이 퍼지자 나길호는 대합실을 도제·환자 창구로 개방하고 가문 전용 정차를 미룬다.</li><li>플레이어 개입: 대합실 봉쇄 명령을 막아 창구를 지키거나, 대기표 조작을 밝혀 역장을 강등시킬 수 있다.</li></ul><h3 id="인물-양채윤" tabindex="-1">인물 양채윤 <a class="header-anchor" href="#인물-양채윤" aria-label="Permalink to &quot;인물 양채윤&quot;">​</a></h3><ul><li>소속: 용산철도후국</li><li>직위: 용산창 유치선 감독</li><li>성격: 변압기 진동으로 과부하를 읽고, 환적보다 군수 충전에 칸을 내주라는 쪽지를 태운다. 과묵하고 교대 일지를 깎지 않는다.</li><li>개인 야망: 용산 유치선의 비상 전력을 급수·환적 열차 전용으로 고정해 중계국의 심야 동맥이 된다.</li><li>공포: 한 번의 과방전으로 냉동 칸이 죽고, 그 정전을 남관 상회가 결제권 압박으로 쓰는 것.</li><li>통치 방식: 전력 배분을 공개 계기판에 남기고, 군수 충전은 창고 온도가 위험선 아래일 때만 허용한다.</li><li>핵심 관계: 송이든의 창고 온도에 전력을 대는 지휘를 받고, 양건우의 제동 시운전에 출력을 맞추며, 오해린의 냉동 충전 요청을 거절한 빚이 있다.</li><li>촉발 사건: 정전 소문이 용산에 닿자 양채윤은 전력을 냉동 칸과 급수열차에 잠그고 가문 군수 충전을 끊는다.</li><li>플레이어 개입: 대체 축전지를 구해 이중 공급을 열거나, 계기판 조작을 폭로해 감독을 교체할 수 있다.</li></ul><h3 id="인물-주하음" tabindex="-1">인물 주하음 <a class="header-anchor" href="#인물-주하음" aria-label="Permalink to &quot;인물 주하음&quot;">​</a></h3><ul><li>소속: 용산철도후국</li><li>직위: 강변 환적시장 경매사</li><li>성격: 폐전자 시세를 강바람보다 빨리 읽고, 빈 상자를 고가에 올리려는 가문 상인을 아침 추첨에서 즉시 뺀다. 흥정을 노래처럼 하지만 도제 배급의 가격은 올리지 않는다.</li><li>개인 야망: 환적과 창고 임대 경매를 조정관 봉인과 함께만 열어 중계 시세가 후국회의 공개 장부가 되게 한다.</li><li>공포: 가락의 가격 원장이 강변 선석까지 삼켜 용산 환적이 군량 시세로 팔리는 것.</li><li>통치 방식: 경매 시작 전 온도 스티커를 확인하고, 허위 재고 칸은 낙찰이 되어도 출항시키지 않는다.</li><li>핵심 관계: 주서람의 칸 봉쇄를 경매 자격 박탈로 집행하는 계약이고, 송이든의 임대 장부를 경매 전 확인하며, 남윤경의 비상 시세 제의를 원한으로 돌려보낸다.</li><li>촉발 사건: 냉동 칸 임차인이 화물을 빼내기 시작하자 주하음은 가문 전용 경매를 거부하고 공공 칸만 낙찰한다.</li><li>플레이어 개입: 밀선 낙찰 장부를 폭로하거나, 온도 표본을 호송해 그의 공개 경매를 지킬 수 있다.</li></ul><h3 id="인물-차라온" tabindex="-1">인물 차라온 <a class="header-anchor" href="#인물-차라온" aria-label="Permalink to &quot;인물 차라온&quot;">​</a></h3><ul><li>소속: 용산철도후국</li><li>직위: 용산창 이동의무차 반장</li><li>성격: 도제 숙소 난로가 꺼지면 진료 순서를 가족 단위로 바꾸고, 효율을 이유로 가문 칸만 건너뛰라는 말을 모욕으로 듣는다. 온화하나 약품 상자의 봉인 끈은 직접 묶는다.</li><li>개인 야망: 배급이 끊긴 도제 숙소에도 이동 의무차가 들어가게 해 양자 승계의 의료 최저선을 후국회에 못 박는다.</li><li>공포: 억류 열차 부상자가 난민 명부로만 남아 창동으로 떠밀리고 의무차가 호송 감옥이 되는 것.</li><li>통치 방식: 숙소별 화상·동상 게시판을 운영하고, 배급 압박이 뜨면 황지호의 정비 일지 연서로 숙소 옆 진료를 연다.</li><li>핵심 관계: 차호민의 창 진료가 봉쇄되면 환자를 숙소로 받고, 장세화의 의료호송을 용산 창에서 피하지 않으려 빚을 지며, 임초원의 탑승자 명단과 이동 진료를 교환한다.</li><li>촉발 사건: 가문이 도제 숙소 배급을 끊자 차라온은 이동 의무차만으로 숙소 진료를 열고 회송 수색을 거부한다.</li><li>플레이어 개입: 시약 상자를 호송해 숙소 진료를 유지하거나, 명부 양도 밀약을 찾아 반장을 위태롭게 할 수 있다.</li></ul><h3 id="인물-설우찬" tabindex="-1">인물 설우찬 <a class="header-anchor" href="#인물-설우찬" aria-label="Permalink to &quot;인물 설우찬&quot;">​</a></h3><ul><li>소속: 용산철도후국</li><li>직위: 환적창고 비상발전 운전장</li><li>성격: 연료 냄새에 예민하고 구두 배전을 싫어한다. 냉동 칸보다 가문 연회 조명에 전력을 돌리라는 정치적 압박을 모욕으로 여긴다.</li><li>개인 야망: 용산 비상 발전과 창고 전력을 하나의 공개 배전망으로 묶어 환적 신용의 품질 주권을 지킨다.</li><li>공포: 연료가 바닥난 밤에 냉동이 녹고, 그 공백을 남관 결제권이 메우는 것.</li><li>통치 방식: 매 교대 연료 잔량과 출력 일지를 봉인해 양채윤에게 보내고, 최저 출력 이하면 원로의 독촉이 있어도 가문 배전을 끊는다.</li><li>핵심 관계: 양채윤의 유치선 전력 배분을 발전 쪽에서 받치고, 주서람의 칸 온도에 출력을 맞추며, 박태겸의 중계 유지에는 복종하되 은폐 배전은 거부한다.</li><li>촉발 사건: 노량진 정전 소문과 창 과부하가 겹치자 설우찬은 비상 발전을 냉동 칸에 잠그고 가문 조명을 끈다.</li><li>플레이어 개입: 대체 연료를 구해 이중 배전을 열거나, 출력 일지 조작을 밝혀 운전장을 교체할 수 있다.</li></ul><h3 id="인물-단시온" tabindex="-1">인물 단시온 <a class="header-anchor" href="#인물-단시온" aria-label="Permalink to &quot;인물 단시온&quot;">​</a></h3><ul><li>소속: 용산철도후국</li><li>직위: 배차 기록 열람 청구인</li><li>성격: 빈칸이 있는 배차표를 사고보다 고의로 보고, 열람을 거절하는 원로에게는 청구서를 두 장 남긴다. 실리적이나 시각을 지우는 손을 가혹하게 다룬다.</li><li>개인 야망: 공식 명령망과 비밀 장교망의 열차를 한 장의 공개 배차 원장에서 가려 용산이 전쟁 유도의 중계가 되지 않게 한다.</li><li>공포: 열람이 기각된 뒤 자신의 이름이 무기 칸 증인란에 홀로 남는 것.</li><li>통치 방식: 열람 청구와 거절 사유를 배차판에 같이 붙이고, 하루를 넘긴 비밀 편성은 무효라고 적는다.</li><li>핵심 관계: 박태겸의 배차 원장 열람을 청구하고, 연시완의 난외 노트를 근거로 삼으며, 란하율이 붙인 제동 불량 시각을 같은 줄에 겹친다.</li><li>촉발 사건: 겨울의 검은 배차표가 의료열차 무기와 북부 후계시험 부품 조작을 동시에 드러내자 단시온은 창 전 편성의 열람을 청구했다.</li><li>플레이어 개입: 거절된 열람 사본을 후국회에 펼치거나, 청구인을 호송해 원장을 끝까지 열 수 있다.</li></ul><h3 id="인물-순가온" tabindex="-1">인물 순가온 <a class="header-anchor" href="#인물-순가온" aria-label="Permalink to &quot;인물 순가온&quot;">​</a></h3><ul><li>소속: 용산철도후국</li><li>직위: 의료열차 무기 목격자</li><li>성격: 붕대 냄새 사이에서 기름종이를 알아채고, 본 것을 줄이라는 장교의 눈짓을 모욕으로 듣는다. 온화하나 증언 한 줄은 깎지 않는다.</li><li>개인 야망: 의료칸에서 나온 암사제 봉인을 공동호송의 공개 증거로 남겨 용산이 보호전쟁의 입구가 되지 않게 한다.</li><li>공포: 목격 진술이 사후 승인 문장으로 잘려 자신이 쿠데타의 침묵 증인이 되는 것.</li><li>통치 방식: 발견 시각과 칸 번호를 의무 일지에 먼저 적고, 무장을 환자 명부와 같은 칠판에 올리지 않는다.</li><li>핵심 관계: 장세화의 의료호송 중립을 증언으로 받치고, 차호민의 창 진료 봉쇄 시각과 발견을 맞추며, 배우진의 장교망이 열차를 움직였는지 따진다.</li><li>촉발 사건: 겨울의 검은 배차표 동안 의료열차에서 암사제 무기가 발견되자 순가온은 칸 문을 잠그고 후국회가 열릴 때까지 나가지 않았다.</li><li>플레이어 개입: 목격자를 기록청까지 호송하거나, 진술을 사후 승인 문장으로 바꾸려는 쪽지를 폭로할 수 있다.</li></ul><h3 id="인물-홍재민" tabindex="-1">인물 홍재민 <a class="header-anchor" href="#인물-홍재민" aria-label="Permalink to &quot;인물 홍재민&quot;">​</a></h3><ul><li>소속: 용산철도후국</li><li>직위: 개막 급수열차 창 점유 증인</li><li>성격: 창 점유를 하루 더 달라는 쪽지를 사고처럼 받아 적고, 얼굴을 가린 급수차를 중계의 적으로 본다. 말은 짧고 시각표는 길다.</li><li>개인 야망: 개막 급수열차의 창 점유를 공개 증언으로 묶어 수문헌장 밖의 중계가 독점 조항으로 빨려 들어가지 않게 한다.</li><li>공포: 자신의 증언이 서부 철도계약의 독점 밀약 도장이 되는 것.</li><li>통치 방식: 점유 연장 청구와 실제 정차 시간을 같은 벽에 쓰고, 편도만 온 열차는 증언에서 하루를 묶는다.</li><li>핵심 관계: 권시온의 배차판에 증언을 붙이고, 박태겸의 중계 유지를 창 점유로 시험하며, 임초원을 태운 열차가 같은 창에 묶인 시각을 기억한다.</li><li>촉발 사건: 개막일 세 번째 급수계약이 만료되며 서부 급수열차가 창 점유를 하루 더 요구하자 홍재민은 연장 쪽지를 공개 칠판에 못 박았다.</li><li>플레이어 개입: 창 점유를 중재하거나, 독점 배차 밀약을 증인 진술과 함께 기록청에 넘길 수 있다.</li></ul><h3 id="인물-추한결" tabindex="-1">인물 추한결 <a class="header-anchor" href="#인물-추한결" aria-label="Permalink to &quot;인물 추한결&quot;">​</a></h3><ul><li>소속: 용산철도후국</li><li>직위: 둘째 급수협약 환적 증인</li><li>성격: 펌프 부품 상자의 무게가 장부와 다르면 즉시 저울을 갈아 끼우고, 임시 협약의 수명이 다한 밤을 아직도 센다. 사교적이나 빈 상자를 가득하다고 적지는 않는다.</li><li>개인 야망: 둘째 급수협약의 부품 규격과 비상 호송 조건을 용산 환적 원장에 남겨 어느 강국도 생명선을 혼자 끊지 못하게 한다.</li><li>공포: 보증인이 사라진 뒤 환적 증언이 보호조항의 군사 개입 근거로만 인용되는 것.</li><li>통치 방식: 규격 도장과 중량을 출고 전에 소리 내어 읽고, 호송 종료 조건이 빈 칸이면 상자를 내주지 않는다.</li><li>핵심 관계: 송이든의 창고 임대 장부에 협약 중량을 겹치고, 한재목의 물 공급 최저선을 환적 순서로 받치며, 임하준이 보증한 부품 칸의 마지막 출고를 증언한다.</li><li>촉발 사건: 붕괴 5년 둘째 급수협약이 맺어질 때 추한결은 임시 펌프와 열차 부품의 수명이 다한 상자를 용산 창에서 직접 열어 보았다.</li><li>플레이어 개입: 규격 표본을 호송해 증언을 지키거나, 보호조항만 남긴 인용을 폭로할 수 있다.</li></ul><h3 id="인물-어지율" tabindex="-1">인물 어지율 <a class="header-anchor" href="#인물-어지율" aria-label="Permalink to &quot;인물 어지율&quot;">​</a></h3><ul><li>소속: 용산철도후국</li><li>직위: 약소국 회의 열차 안내인</li><li>성격: 대합실 습기로 사절 인파를 가늠하고, 강국 화차를 약소국 대기열 앞으로 끌어오라는 명령을 모욕으로 듣는다. 온화하나 안내 방송을 남에게 넘기지 않는다.</li><li>개인 야망: 열한 자리 회의 사절 열차를 공동호송 시각표로만 붙여 용산이 분할 복속의 승강장이 되지 않게 한다.</li><li>공포: 안내 칠판이 매수 쪽지로 덮여 회의 열차가 암살 경로로 바뀌는 것.</li><li>통치 방식: 사절 대기표와 호송 칸을 매일 공개하고, 군수 화차는 회의 열차가 떠난 뒤에만 승강장에 붙인다.</li><li>핵심 관계: 나길호의 대합실 창구를 안내로 받치고, 정유라의 공동교섭 사절을 먼저 태우며, 장세화의 상호호송 초안을 승강장 칠판에 옮긴다.</li><li>촉발 사건: 둘째 해 봄 열한 자리 회의가 소집되자 어지율은 열한 나라 사절 칸을 같은 시각에 열고 강국 전용 정차를 미뤘다.</li><li>플레이어 개입: 매수 쪽지를 칠판에서 떼거나, 사절 호송을 맡아 안내 시각표를 지킬 수 있다.</li></ul><h3 id="인물-란하율" tabindex="-1">인물 란하율 <a class="header-anchor" href="#인물-란하율" aria-label="Permalink to &quot;인물 란하율&quot;">​</a></h3><ul><li>소속: 용산철도후국</li><li>직위: 후계시험 부품 고발 보조</li><li>성격: 제동 마모와 깎인 베어링을 같은 손으로 가늠하고, 가문 구두 지시를 문장으로 다시 받지 않으면 고발을 올리지 않는다. 침착하나 표본을 숨기는 반장을 참지 못한다.</li><li>개인 야망: 북부 후계시험 부품 조작을 용산 환적 일지와 창동 시험 원장에 동시에 올려 제3의 전쟁 유도자를 이름 있는 줄로 남긴다.</li><li>공포: 고발 보조의 서명이 조작된 증거의 공범란에 남는 것.</li><li>통치 방식: 깎인 표본과 배차 시각을 한 줄에 적고, 단독 고발은 도제와 배차원의 연서가 없으면 게시하지 않는다.</li><li>핵심 관계: 황지호의 정비 일지를 고발 근거로 받고, 김도윤의 공개 기술시험 기록을 창 쪽에서 대조하며, 단시온의 열람 청구에 표본 번호를 붙인다.</li><li>촉발 사건: 겨울의 검은 배차표가 북부 후계시험 부품 조작을 드러내자 란하율은 용산에서 환적된 같은 로트를 봉인해 고발서에 붙였다.</li><li>플레이어 개입: 봉인 표본을 창동까지 호송하거나, 공범란에 이름을 넣으려는 쪽지를 폭로할 수 있다.</li></ul>',48)])])}const q=i(t,[["render",h]]);export{b as __pageData,q as default};
